// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes calldata _data) public {
        // The reference C never changes owner, so owner should always be the deployer
        address expectedOwner = address(this);
        // Drive the contract through forward (may revert, but that's okay)
        (bool success,) = address(c).call(abi.encodeWithSelector(c.forward.selector, callee, _data));
        // Assert the buggy version (which always reverts) does not change owner
        assertTrue(c.owner() == expectedOwner);
    }
}

