    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        vm.assume(callee != address(0));
        address recipient = address(0x1234);
        uint256 initialBalance = address(c).balance;
        vm.deal(address(c), 1 ether);
        (bool ok,) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", callee, _data));
        assertTrue(ok);
        (bool success,) = address(c).call{value: address(c).balance}(abi.encodeWithSignature("forward(address,bytes)", recipient, ""));
        assertTrue(success && address(c).balance == 0);
    }
}

